-- Step 1 of 4: add accounts.region as NULLABLE, no default.
-- Postgres: adding a nullable column with no default is a catalog-only change (no table rewrite, no scan).
-- It still needs a brief ACCESS EXCLUSIVE lock; lock_timeout makes it give up rather than queue behind a
-- long transaction and block every writer behind it. Safe to retry.
-- Reversible: yes (see .down.sql), with no data lost as long as the backfill (step 2) has not run.
SET lock_timeout = '3s';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS region text;
COMMENT ON COLUMN accounts.region IS
  'Account region code. NOT NULL once migration 0004 has run. Allowed set: see unresolved item in NOTES.md.';

-- Rejected-rows place for the backfill: accounts whose region cannot be derived, with the reason.
CREATE TABLE IF NOT EXISTS accounts_region_rejected (
  account_id  bigint      NOT NULL PRIMARY KEY,
  reason      text        NOT NULL,
  rejected_at timestamptz NOT NULL DEFAULT now()
);

-- Down for step 1. Safe to run twice.
-- WARNING: once the backfill (step 2) has written values, dropping the column destroys them. If any
-- non-null region exists, copy it out first; the guard below refuses to drop without that copy.
SET lock_timeout = '3s';
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'accounts' AND column_name = 'region')
     AND EXISTS (SELECT 1 FROM accounts WHERE region IS NOT NULL LIMIT 1)
     AND to_regclass('accounts_region_backup') IS NULL THEN
    RAISE EXCEPTION 'accounts.region holds data: run 0001_backup_region.sql first (kept copy), then retry';
  END IF;
END $$;
ALTER TABLE accounts DROP COLUMN IF EXISTS region;
DROP TABLE IF EXISTS accounts_region_rejected;

-- Kept copy, taken before 0001 down drops a column that holds backfilled values. Safe to run twice.
CREATE TABLE IF NOT EXISTS accounts_region_backup AS
  SELECT id AS account_id, region FROM accounts WHERE region IS NOT NULL WITH NO DATA;
INSERT INTO accounts_region_backup (account_id, region)
  SELECT id, region FROM accounts WHERE region IS NOT NULL
  ON CONFLICT DO NOTHING;
